from collections import deque, Counter, defaultdict

def components(grid, match=lambda v: v != 0):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for y in range(h):
        for x in range(w):
            if (y,x) in seen or not match(grid[y][x]): continue
            val=grid[y][x]; q=[(y,x)]; seen.add((y,x)); pts=[]
            while q:
                cy,cx=q.pop(); pts.append((cy,cx))
                for ny,nx in ((cy-1,cx),(cy+1,cx),(cy,cx-1),(cy,cx+1)):
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and match(grid[ny][nx]) and grid[ny][nx]==val:
                        seen.add((ny,nx));q.append((ny,nx))
            out.append((val,pts))
    return out

def normshape(pts):
    ys=[p[0] for p in pts]; xs=[p[1] for p in pts]; my,mx=min(ys),min(xs)
    return tuple(sorted((y-my,x-mx) for y,x in pts))

top_grid=[r[0:30] for r in rows[0:7]]
topcomps=components(top_grid, lambda v:v==1)
[(len(p), (min(y for y,x in p),min(x for y,x in p),max(y for y,x in p),max(x for y,x in p)), normshape(p)) for v,p in topcomps]
